const input = (items[0] && items[0].json) || {};
const constants = {
  workflow_version: 'psy_05_terms_questions_v1',
  workflow_name: 'psy_05_terms_questions',
  llm_model: 'deepseek-flash',
  thinking: { type: 'disabled' },
  temperature_terms: 0.2,
  temperature_questions: 0.5,
  max_output_tokens: 8000,
  // DeepSeek peak prices, USD per 1M tokens (conservative; off-peak discount ignored).
  prices_usd_per_1m: { tier: 'peak', miss: 0.3, hit: 0.006, out: 1.2 },
  monthly_budget_usd: 5,
  budget_stop_ratio: 0.8,
  max_cost_usd_per_lecture: 0.3,
  chars_per_token: 2,
  terms_max_input_tokens: 80000,
  est_output_tokens_terms: 6000,
  est_output_tokens_questions: 6000,
  est_input_tokens_questions: 12000,
  est_subtopics_for_budget: 8,
  questions_target: 10,
  max_questions_per_subtopic: 14,
  questions_transcript_max_chars: 20000,
  prompt_versions: { terms: 'extract_terms_v2', questions: 'gen_questions_v2' },
  max_attempts: 3,
  stale_running_hours: 4,
};
// In — Execute may only LOWER these limits (never raise).
['max_cost_usd_per_lecture', 'monthly_budget_usd'].forEach((key) => {
  const v = Number(input[key]);
  if (Number.isFinite(v) && v > 0 && v < constants[key]) constants[key] = v;
});
return [{ json: { constants }, pairedItem: 0 }];

const C = $('Run — Init Constants').first().json.constants;
const row = items[0].json;
const SYSTEM = "Ты выделяешь подтемы и термины одной лекции. Источник — только блоки этого сообщения. Не добавляй понятия, определения и примеры из других лекций и из общих знаний.\n\nВход:\nМЕТАДАННЫЕ\nГЛОССАРИЙ — уже известные написания, может быть пуст\nКОНСПЕКТ\nТРАНСКРИПТ\n\nПравила:\n- Подтема — отдельный учебный узел этой лекции, в порядке изложения. ordinal с 1. Не дроби лекцию на одну подтему и не копируй оглавление чужого курса.\n- Термин — имя понятия, которое лектор здесь употребляет. Бытовые слова, имена людей и разовый пример термином не являются.\n- definition — только формулировка из этой лекции. Нет формулировки — null. Дыру `[неразборчиво]` не раскрывай.\n- life_example — 1–2 предложения бытовой ситуации, которая иллюстрирует definition из этой лекции. Не вводит новых фактов. Если definition = null, то life_example = null.\n- canonical — написание из ГЛОССАРИЙ, если термин там есть; иначе как в конспекте.\n- aliases — только другие написания из глоссария или явная оговорка лектора. Не выдумывай варианты.\n- subtopic_ordinal — подтема, в которой термин разбирается. Нет явной подтемы — ближайшая по тексту.\n\nОтвет — один JSON-объект без Markdown и без текста вокруг:\n\n{\"subtopics\":[{\"ordinal\":1,\"title\":\"...\"}],\"terms\":[{\"canonical\":\"...\",\"aliases\":[],\"definition\":null,\"life_example\":null,\"subtopic_ordinal\":1}]}\n\nПустая лекция — пустые массивы. Не объясняй ответ.";
const cpt = C.chars_per_token || 2;
const est = (s) => Math.ceil(String(s || '').length / cpt);

const metaLines = ['МЕТАДАННЫЕ', 'Название: ' + (row.title || '[неизвестно]')];
if (row.duration_sec) metaLines.push('Длительность: ' + Math.round(Number(row.duration_sec) / 60) + ' мин');
if (row.lecturer_name) metaLines.push('Лектор: ' + row.lecturer_name);
const head = [
  metaLines.join('\n'),
  'ГЛОССАРИЙ\n' + (row.glossary || ''),
  'КОНСПЕКТ\n' + String(row.konspekt_md || '').trim(),
].join('\n\n');

let transcript = String(row.transcript || '').trim();
let truncated = false;
const room = (C.terms_max_input_tokens - est(SYSTEM) - est(head) - 200) * cpt;
if (transcript.length > room) {
  transcript = transcript.slice(0, Math.max(room, 0)) + '\n[транскрипт усечён по лимиту токенов]';
  truncated = true;
}
const user = head + '\n\nТРАНСКРИПТ\n' + transcript;

const P = C.prices_usd_per_1m;
const inTokens = est(SYSTEM) + est(user);
const termsCost = (inTokens * P.miss + C.est_output_tokens_terms * P.out) / 1e6;
const questionCall = (C.est_input_tokens_questions * P.miss + C.est_output_tokens_questions * P.out) / 1e6;
const projected = termsCost + C.est_subtopics_for_budget * questionCall;
const spentLecture = Number(row.spent_lecture_usd) || 0;
const spentMonth = Number(row.spent_month_usd) || 0;
const lectureCap = C.max_cost_usd_per_lecture;
const monthCap = C.monthly_budget_usd * C.budget_stop_ratio;
let reason = null;
if (spentLecture + projected > lectureCap) {
  reason = 'budget_exceeded: лимит на лекцию ' + lectureCap + ' USD (потрачено ' + spentLecture.toFixed(4)
    + ', прогноз терминов+вопросов ' + projected.toFixed(4) + ')';
} else if (spentMonth + projected > monthCap) {
  reason = 'budget_exceeded: 80% месячного бюджета ' + C.monthly_budget_usd + ' USD (потрачено '
    + spentMonth.toFixed(4) + ', прогноз ' + projected.toFixed(4) + ')';
}
if (reason) {
  return [{ json: { budget_exceeded: true, error_message: reason, lecture_id: row.lecture_id, job_id: row.job_id }, pairedItem: 0 }];
}
return [{
  json: {
    budget_exceeded: false,
    lecture_id: row.lecture_id,
    job_id: row.job_id,
    course_id: row.course_id,
    step: 'terms',
    prompt_version: C.prompt_versions.terms,
    transcript_truncated: truncated,
    projected_cost_usd: Number(projected.toFixed(5)),
    request_body: {
      model: C.llm_model,
      messages: [
        { role: 'system', content: SYSTEM },
        { role: 'user', content: user },
      ],
      thinking: C.thinking,
      response_format: { type: 'json_object' },
      max_tokens: C.max_output_tokens,
      temperature: C.temperature_terms,
      stream: false,
    },
  },
  pairedItem: 0,
}];

const C = $('Run — Init Constants').first().json.constants;
const src = $('LLM — Build Terms Request').first().json;
function parseDeepSeek(resp, C, src, step, promptVersion) {
  const r = resp || {};
  const choice = (r.choices && r.choices[0]) || {};
  const content = String((choice.message && choice.message.content) || '');
  const u = r.usage || {};
  const hit = Number(u.prompt_cache_hit_tokens != null
    ? u.prompt_cache_hit_tokens
    : ((u.prompt_tokens_details && u.prompt_tokens_details.cached_tokens) || 0)) || 0;
  let miss = u.prompt_cache_miss_tokens != null ? Number(u.prompt_cache_miss_tokens) : null;
  const promptTokens = Number(u.prompt_tokens != null ? u.prompt_tokens : ((miss || 0) + hit)) || 0;
  if (miss == null || !Number.isFinite(miss)) miss = Math.max(promptTokens - hit, 0);
  const completion = Number(u.completion_tokens) || 0;
  const P = C.prices_usd_per_1m;
  const costExact = (miss * P.miss + hit * P.hit + completion * P.out) / 1e6;
  return {
    content,
    finish_reason: choice.finish_reason || null,
    cost_exact: costExact,
    usage_row: {
      lecture_id: src.lecture_id,
      job_id: src.job_id,
      workflow_name: C.workflow_name,
      workflow_version: C.workflow_version,
      model: r.model || C.llm_model,
      prompt_tokens: promptTokens,
      completion_tokens: completion,
      cost_usd: Number(costExact.toFixed(6)),
      prompt_version: promptVersion,
      prompt_cache_hit_tokens: hit,
      step,
    },
  };
}
const p = parseDeepSeek(items[0].json, C, src, 'terms', C.prompt_versions.terms);

function parseJson(text) {
  let t = String(text || '').trim();
  const m = t.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/);
  if (m) t = m[1];
  try {
    return { value: JSON.parse(t) };
  } catch (e) {
    const a = t.indexOf('{');
    const b = t.lastIndexOf('}');
    if (a >= 0 && b > a) {
      try {
        return { value: JSON.parse(t.slice(a, b + 1)) };
      } catch (e2) {
        /* fall through */
      }
    }
    return { error: 'invalid_json' };
  }
}

const result = {
  lecture_id: src.lecture_id,
  job_id: src.job_id,
  usage_row: p.usage_row,
  cost_exact: p.cost_exact,
  finish_reason: p.finish_reason,
  transcript_truncated: src.transcript_truncated,
  ok: false,
  error_message: null,
  subtopics: [],
  terms: [],
};

function fail(msg) {
  result.error_message = msg;
  return [{ json: result, pairedItem: 0 }];
}

if (!p.content.trim()) return fail('llm_empty_response (terms)');
const pj = parseJson(p.content);
if (pj.error) {
  return fail(p.finish_reason === 'length' ? 'llm_truncated: finish_reason=length (terms)' : 'terms: invalid_json');
}
const data = pj.value;
if (!data || typeof data !== 'object' || !Array.isArray(data.subtopics) || !Array.isArray(data.terms)) {
  return fail('terms: schema (нужны subtopics[] и terms[])');
}

const subs = [];
const seen = new Set();
for (const s of data.subtopics) {
  const ordinal = Number(s && s.ordinal);
  const title = String((s && s.title) || '').trim();
  if (!Number.isInteger(ordinal) || ordinal < 1 || !title || seen.has(ordinal)) continue;
  seen.add(ordinal);
  subs.push({ ordinal, title });
}
subs.sort((a, b) => a.ordinal - b.ordinal);
if (!subs.length) return fail('terms: empty_subtopics');

const byKey = new Map();
for (const t of data.terms) {
  const canonical = String((t && t.canonical) || '').trim();
  if (!canonical) continue;
  const aliases = Array.isArray(t.aliases)
    ? t.aliases.map((a) => String(a || '').trim()).filter((a) => a && a !== canonical)
    : [];
  let definition = t.definition == null ? null : String(t.definition).trim() || null;
  let lifeExample = definition && t.life_example != null ? String(t.life_example).trim() || null : null;
  let so = Number(t.subtopic_ordinal);
  if (!seen.has(so)) {
    const lower = subs.filter((s) => s.ordinal <= so).pop();
    so = lower ? lower.ordinal : subs[0].ordinal;
  }
  const key = canonical.toLowerCase();
  if (byKey.has(key)) {
    const prev = byKey.get(key);
    prev.aliases = Array.from(new Set(prev.aliases.concat(aliases)));
    if (!prev.definition && definition) {
      prev.definition = definition;
      prev.life_example = lifeExample;
    }
    continue;
  }
  byKey.set(key, { canonical, aliases: Array.from(new Set(aliases)), definition, life_example: lifeExample, subtopic_ordinal: so });
}
const terms = Array.from(byKey.values());
if (!terms.length) return fail('terms: empty_terms');

result.ok = true;
result.subtopics = subs;
result.terms = terms;
return [{ json: result, pairedItem: 0 }];

const C = $('Run — Init Constants').first().json.constants;
const L = $('Load — Lecture').first().json;
const T = $('LLM — Parse Terms').first().json;
const sub = items[0].json;
const SYSTEM = "Ты пишешь вопросы с выбором ответа по одной подтеме одной лекции. Сразу JSON, без рассуждений вслух.\n\nВход — одна подтема:\nПОДТЕМА — ordinal и title\nТЕРМИНЫ — canonical и definition только этой подтемы\nФРАГМЕНТ КОНСПЕКТА\nФРАГМЕНТ ТРАНСКРИПТА\nОПЦИОНАЛЬНО: ОШИБКИ_ВАЛИДАЦИИ или ДОБОР — короткий список, что исправить или сколько вопросов не хватает\n\nПиши только по этим блокам. Не переноси факты из других подтем и лекций. Не добавляй термины, цифры, диагнозы и детали случаев, которых во фрагменте нет. `[неразборчиво]` не заполняй.\n\nЦель — не меньше 10 вопросов. Каждый — жизненная ситуация: человек и бытовой контекст, затем что из этого следует по лекции. Не спрашивай определение в лоб и не проси назвать термин.\n\nЧетыре коротких варианта, A–D, ровно один верный. Верный следует из фрагмента. Неверные — близкая путаница по этой же подтеме. Если фактов мало, меняй ситуации, не факты. Не повторяй один и тот же stem.\n\nК каждому варианту — одно короткое предложение: почему он сходится или расходится с лекцией. explanation — 2–4 предложения ученику, который ошибся. Новых фактов нет.\n\nterm_canonical — только из списка ТЕРМИНЫ. kind всегда \"life_mcq\". correct_choice — одна буква A, B, C или D.\n\nЕсли честно не набирается 10 вопросов без выдумки, верни сколько есть и \"shortfall\": true. Не выдумывай факты ради десятки.\n\nПеред ответом проверь: один верный, четыре пояснения на месте, нет факта вне фрагмента.\n\nОтвет — один JSON без Markdown:\n\n{\"subtopic_ordinal\":1,\"shortfall\":false,\"questions\":[{\"term_canonical\":\"...\",\"kind\":\"life_mcq\",\"stem\":\"...\",\"choice_a\":\"...\",\"choice_b\":\"...\",\"choice_c\":\"...\",\"choice_d\":\"...\",\"correct_choice\":\"A\",\"explanation\":\"...\",\"explanation_a\":\"...\",\"explanation_b\":\"...\",\"explanation_c\":\"...\",\"explanation_d\":\"...\"}]}";
const cpt = C.chars_per_token || 2;
const est = (s) => Math.ceil(String(s || '').length / cpt);

const norm = (s) => String(s || '').toLowerCase().replace(/ё/g, 'е');
function stems(phrase) {
  return norm(phrase)
    .split(/[^а-яa-z0-9]+/)
    .filter((w) => w.length >= 4)
    .map((w) => w.slice(0, Math.max(4, w.length - 2)));
}
function matcher(names) {
  const sets = names.map(stems).filter((s) => s.length);
  const plain = names.map(norm).filter((p) => p && p.length < 4);
  return (text) => {
    const t = norm(text);
    if (sets.some((set) => set.every((s) => t.includes(s)))) return true;
    return plain.some((p) => t.includes(p));
  };
}

const subTerms = T.terms.filter((t) => t.subtopic_ordinal === sub.ordinal && t.definition);
const base = {
  lecture_id: L.lecture_id,
  job_id: L.job_id,
  course_id: L.course_id,
  subtopic_id: sub.subtopic_id,
  ordinal: sub.ordinal,
  title: sub.title,
  spent_month_usd: Number(sub.spent_month_usd) || 0,
  spent_lecture_usd: Number(sub.spent_lecture_usd) || 0,
  term_canonicals: subTerms.map((t) => t.canonical),
  existing_stems: [],
  step: 'questions',
  prompt_version: C.prompt_versions.questions,
};
if (!subTerms.length) {
  return [{ json: { ...base, skip: true, budget_exceeded: false, skip_reason: 'no_terms_with_definition' }, pairedItem: 0 }];
}

// --- konspekt fragment: sections that mention the subtopic's terms / title words
const konspekt = String(L.konspekt_md || '').trim();
const termNames = subTerms.flatMap((t) => [t.canonical].concat(t.aliases || []));
const termMatch = matcher(termNames);
const titleStems = stems(sub.title);
const sections = konspekt.split(/\n(?=##\s)/);
const scored = sections.map((text, idx) => {
  const t = norm(text);
  let score = subTerms.filter((st) => matcher([st.canonical].concat(st.aliases || []))(text)).length * 2;
  score += titleStems.filter((s) => t.includes(s)).length;
  return { idx, text, score };
});
let picked = scored.filter((s) => s.score > 0).sort((a, b) => b.score - a.score).slice(0, 3).sort((a, b) => a.idx - b.idx);
let konspektFragment = picked.length ? picked.map((s) => s.text).join('\n\n') : konspekt;
if (konspektFragment.length > 12000) konspektFragment = konspektFragment.slice(0, 12000);

// --- transcript fragment: segments mentioning the terms (+/- 1 neighbour), capped
let segs = (Array.isArray(L.chunks) ? L.chunks : []).map((c) => String((c && c.text) || '').trim());
if (!segs.filter(Boolean).length) {
  const tr = String(L.transcript || '');
  segs = [];
  for (let i = 0; i < tr.length; i += 1000) segs.push(tr.slice(i, i + 1000));
}
const hit = new Set();
segs.forEach((text, i) => {
  if (text && termMatch(text)) {
    hit.add(i);
    if (i > 0) hit.add(i - 1);
    if (i + 1 < segs.length) hit.add(i + 1);
  }
});
const order = Array.from(hit).sort((a, b) => a - b);
const parts = [];
let used = 0;
for (const i of order) {
  const text = segs[i];
  if (!text) continue;
  if (used + text.length > C.questions_transcript_max_chars) break;
  parts.push(text);
  used += text.length + 1;
}
const transcriptFragment = parts.length ? parts.join('\n') : '[фрагмент не найден — опирайся только на конспект]';

const termsBlock = subTerms.map((t) => '- ' + t.canonical + ': ' + t.definition).join('\n');
const user = [
  'ПОДТЕМА\n' + sub.ordinal + '. ' + sub.title,
  'ТЕРМИНЫ\n' + termsBlock,
  'ФРАГМЕНТ КОНСПЕКТА\n' + konspektFragment,
  'ФРАГМЕНТ ТРАНСКРИПТА\n' + transcriptFragment,
].join('\n\n');

const P = C.prices_usd_per_1m;
const inTokens = est(SYSTEM) + est(user);
const projected = (inTokens * P.miss + C.est_output_tokens_questions * P.out) / 1e6;
const lectureCap = C.max_cost_usd_per_lecture;
const monthCap = C.monthly_budget_usd * C.budget_stop_ratio;
let reason = null;
if (base.spent_lecture_usd + projected > lectureCap) {
  reason = 'budget_exceeded: лимит на лекцию ' + lectureCap + ' USD перед подтемой ' + sub.ordinal
    + ' (потрачено ' + base.spent_lecture_usd.toFixed(4) + ')';
} else if (base.spent_month_usd + projected > monthCap) {
  reason = 'budget_exceeded: 80% месячного бюджета ' + C.monthly_budget_usd + ' USD перед подтемой ' + sub.ordinal
    + ' (потрачено ' + base.spent_month_usd.toFixed(4) + ')';
}
if (reason) {
  return [{ json: { ...base, skip: false, budget_exceeded: true, error_message: reason }, pairedItem: 0 }];
}
return [{
  json: {
    ...base,
    skip: false,
    budget_exceeded: false,
    est_input_tokens: inTokens,
    user_base: user,
    request_body: {
      model: C.llm_model,
      messages: [
        { role: 'system', content: SYSTEM },
        { role: 'user', content: user },
      ],
      thinking: C.thinking,
      response_format: { type: 'json_object' },
      max_tokens: C.max_output_tokens,
      temperature: C.temperature_questions,
      stream: false,
    },
  },
  pairedItem: 0,
}];

const C = $('Run — Init Constants').first().json.constants;
const b = $('LLM — Build Questions Request').first().json;
function parseDeepSeek(resp, C, src, step, promptVersion) {
  const r = resp || {};
  const choice = (r.choices && r.choices[0]) || {};
  const content = String((choice.message && choice.message.content) || '');
  const u = r.usage || {};
  const hit = Number(u.prompt_cache_hit_tokens != null
    ? u.prompt_cache_hit_tokens
    : ((u.prompt_tokens_details && u.prompt_tokens_details.cached_tokens) || 0)) || 0;
  let miss = u.prompt_cache_miss_tokens != null ? Number(u.prompt_cache_miss_tokens) : null;
  const promptTokens = Number(u.prompt_tokens != null ? u.prompt_tokens : ((miss || 0) + hit)) || 0;
  if (miss == null || !Number.isFinite(miss)) miss = Math.max(promptTokens - hit, 0);
  const completion = Number(u.completion_tokens) || 0;
  const P = C.prices_usd_per_1m;
  const costExact = (miss * P.miss + hit * P.hit + completion * P.out) / 1e6;
  return {
    content,
    finish_reason: choice.finish_reason || null,
    cost_exact: costExact,
    usage_row: {
      lecture_id: src.lecture_id,
      job_id: src.job_id,
      workflow_name: C.workflow_name,
      workflow_version: C.workflow_version,
      model: r.model || C.llm_model,
      prompt_tokens: promptTokens,
      completion_tokens: completion,
      cost_usd: Number(costExact.toFixed(6)),
      prompt_version: promptVersion,
      prompt_cache_hit_tokens: hit,
      step,
    },
  };
}
/**
 * Validate gen_questions_v2 JSON for one subtopic.
 * Pure function — no I/O. Used from n8n Code node and node:test.
 */

function normalizeChoice(text) {
  return String(text || '')
    .toLowerCase()
    .replace(/[\s\u00a0]+/g, ' ')
    .replace(/[.,;:!?…]+$/g, '')
    .trim();
}

function normalizeStem(text) {
  return normalizeChoice(text);
}

/**
 * @param {unknown} raw parsed JSON (object) or string
 * @param {{ termCanonicals: string[], existingStems?: string[] }} ctx
 * @returns {{ ok: boolean, errors: string[], data?: object, validQuestions?: object[] }}
 */
function validateQuestionsPayload(raw, ctx) {
  const errors = [];
  const termSet = new Set((ctx.termCanonicals || []).map((t) => String(t)));
  const existingStems = new Set((ctx.existingStems || []).map(normalizeStem));

  let data = raw;
  if (typeof raw === 'string') {
    try {
      data = JSON.parse(raw);
    } catch {
      return { ok: false, errors: ['invalid_json'] };
    }
  }

  if (!data || typeof data !== 'object' || Array.isArray(data)) {
    return { ok: false, errors: ['not_object'] };
  }

  const allowedTop = new Set(['subtopic_ordinal', 'shortfall', 'questions']);
  for (const key of Object.keys(data)) {
    if (!allowedTop.has(key)) errors.push(`extra_field:${key}`);
  }

  if (typeof data.subtopic_ordinal !== 'number' || data.subtopic_ordinal < 1) {
    errors.push('bad_subtopic_ordinal');
  }
  if (typeof data.shortfall !== 'boolean') {
    errors.push('bad_shortfall');
  }
  if (!Array.isArray(data.questions)) {
    errors.push('questions_not_array');
    return { ok: false, errors };
  }

  const allowedQ = new Set([
    'term_canonical',
